package com.recipeagent.model;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A recipe generated by the agent (F01) and saved in the history (F08). */
public class Recipe {

    /** Rating value for a recipe the user has not rated yet. */
    public static final int UNRATED = 0;

    private String id;
    private String title;
    private List<Ingredient> ingredients;
    private List<String> steps;
    private int cookTimeMinutes;
    private int portions;
    private int rating;
    private boolean favourite;
    private List<LocalDate> cookedOn;
    /** Ingredient name (lower case) of a substitute -> the pantry items it is made from (F07). */
    private Map<String, List<String>> substituteParts;

    /** Creates a new, unrated recipe with a generated id. */
    public Recipe(String title, List<Ingredient> ingredients, List<String> steps,
                  int cookTimeMinutes, int portions) {
        this(UUID.randomUUID().toString(), title, ingredients, steps, cookTimeMinutes, portions);
    }

    /** Creates a recipe with a known id, e.g. when loading from storage. */
    public Recipe(String id, String title, List<Ingredient> ingredients, List<String> steps,
                  int cookTimeMinutes, int portions) {
        this.id = Validation.requireText(id, "Recipe id");
        this.title = Validation.requireText(title, "Recipe title");
        this.ingredients = new ArrayList<>(ingredients == null ? List.of() : ingredients);
        this.steps = new ArrayList<>(steps == null ? List.of() : steps);
        this.cookTimeMinutes = Validation.requirePositive(cookTimeMinutes, "Cooking time");
        this.portions = Validation.requirePositive(portions, "Portions");
        this.rating = UNRATED;
        this.favourite = false;
        this.cookedOn = new ArrayList<>();
    }

    public String getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public List<Ingredient> getIngredients() {
        return Collections.unmodifiableList(ingredientList());
    }

    public List<String> getSteps() {
        if (steps == null) {
            steps = new ArrayList<>();
        }
        return Collections.unmodifiableList(steps);
    }

    public int getCookTimeMinutes() {
        return cookTimeMinutes;
    }

    public int getPortions() {
        return portions;
    }

    public int getRating() {
        return rating;
    }

    public boolean isRated() {
        return rating != UNRATED;
    }

    /**
     * Sets a 1-5 star rating (F08).
     *
     * @throws IllegalArgumentException if stars is outside 1-5
     */
    public void setRating(int stars) {
        if (stars < 1 || stars > 5) {
            throw new IllegalArgumentException("Rating must be between 1 and 5, got " + stars);
        }
        this.rating = stars;
    }

    public boolean isFavourite() {
        return favourite;
    }

    public void setFavourite(boolean favourite) {
        this.favourite = favourite;
    }

    /** Flips the favourite flag and returns the new value (F08). */
    public boolean toggleFavourite() {
        favourite = !favourite;
        return favourite;
    }

    /** Records that the user cooked this recipe on {@code date} (F06). */
    public void recordCooked(LocalDate date) {
        if (date == null) {
            throw new IllegalArgumentException("Cook date must not be null");
        }
        cookDates().add(date);
    }

    /**
     * Removes the most recent cook record, used when Mark as Cooked is undone (F06).
     *
     * @return true if there was a record to remove
     */
    public boolean removeLastCooked() {
        List<LocalDate> dates = cookDates();
        if (dates.isEmpty()) {
            return false;
        }
        dates.remove(dates.size() - 1);
        return true;
    }

    public int getTimesCooked() {
        return cookDates().size();
    }

    /** The last date this recipe was cooked, or null if never. */
    public LocalDate getLastCooked() {
        List<LocalDate> dates = cookDates();
        return dates.isEmpty() ? null : dates.get(dates.size() - 1);
    }

    /**
     * Replaces an ingredient with a substitute (F07 "Use substitute"). The substitute keeps
     * the original amount, and the steps are updated to name it. If the recipe already has
     * the substitute with the same unit, the amounts are added together instead.
     *
     * @return false if the recipe has no ingredient called {@code oldName}
     * @throws IllegalArgumentException if the substitute name is blank
     */
    public boolean replaceIngredient(String oldName, String substitute) {
        return replaceIngredient(oldName, substitute, List.of());
    }

    /**
     * Same as {@link #replaceIngredient(String, String)}, and remembers which pantry items the
     * substitute is made from (e.g. "milk with lemon juice" uses milk and lemon), so the
     * ingredient check can find it in the pantry although no item has that exact name.
     */
    public boolean replaceIngredient(String oldName, String substitute, List<String> pantryItems) {
        String newName = Validation.requireText(substitute, "Substitute");
        if (oldName == null) {
            return false;
        }
        List<Ingredient> list = ingredientList();
        int index = indexOf(oldName.trim());
        if (index < 0) {
            return false;
        }
        Ingredient old = list.get(index);
        if (old.getName().equalsIgnoreCase(newName)) {
            return true;
        }
        int same = indexOf(newName);
        if (same >= 0 && list.get(same).getUnit().equalsIgnoreCase(old.getUnit())) {
            Ingredient existing = list.get(same);
            list.set(same, new Ingredient(existing.getName(),
                    existing.getQuantity() + old.getQuantity(), existing.getUnit()));
            list.remove(index);
        } else {
            list.set(index, new Ingredient(newName, old.getQuantity(), old.getUnit()));
            List<String> parts = new ArrayList<>();
            for (String p : pantryItems == null ? List.<String>of() : pantryItems) {
                if (p != null && !p.isBlank()) {
                    parts.add(p.trim());
                }
            }
            if (!parts.isEmpty()) {
                parts().put(key(newName), parts);
            }
        }
        parts().remove(key(old.getName()));
        renameInSteps(old.getName(), newName);
        return true;
    }

    /**
     * The pantry items a substitute ingredient is made from, or an empty list for a normal
     * ingredient (or a substitute that is not made from pantry items).
     */
    public List<String> getSubstituteParts(String ingredientName) {
        if (ingredientName == null) {
            return List.of();
        }
        List<String> parts = parts().get(key(ingredientName));
        return parts == null ? List.of() : Collections.unmodifiableList(parts);
    }

    private static String key(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    /** Older saved files have no substitutes, so create the map when first needed. */
    private Map<String, List<String>> parts() {
        if (substituteParts == null) {
            substituteParts = new HashMap<>();
        }
        return substituteParts;
    }

    private int indexOf(String name) {
        List<Ingredient> list = ingredientList();
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).getName().equalsIgnoreCase(name)) {
                return i;
            }
        }
        return -1;
    }

    /** Replaces the old ingredient name in the steps (whole words, any case). */
    private void renameInSteps(String oldName, String newName) {
        Pattern p = Pattern.compile("(?<![\\p{L}\\p{N}])" + Pattern.quote(oldName) + "(?![\\p{L}\\p{N}])",
                Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
        if (steps == null) {
            steps = new ArrayList<>();
        }
        for (int i = 0; i < steps.size(); i++) {
            steps.set(i, p.matcher(steps.get(i)).replaceAll(Matcher.quoteReplacement(newName)));
        }
    }

    /** A saved file may leave out the ingredient list, so create it when first needed. */
    private List<Ingredient> ingredientList() {
        if (ingredients == null) {
            ingredients = new ArrayList<>();
        }
        return ingredients;
    }

    /** Older saved files have no cook list, so create it when first needed. */
    private List<LocalDate> cookDates() {
        if (cookedOn == null) {
            cookedOn = new ArrayList<>();
        }
        return cookedOn;
    }

    /** True if the title or any ingredient name contains {@code query}, ignoring case (F08 search). */
    public boolean matches(String query) {
        if (query == null || query.isBlank()) {
            return true;
        }
        String q = query.trim().toLowerCase(Locale.ROOT);
        if (title.toLowerCase(Locale.ROOT).contains(q)) {
            return true;
        }
        for (Ingredient i : ingredientList()) {
            if (i.getName().toLowerCase(Locale.ROOT).contains(q)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public String toString() {
        return title + " (" + cookTimeMinutes + " min, " + portions + " portions)";
    }
}
